const ico=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baseDesign={length:56,sleeve:48,ease:12,color:'#aaa2d6',colorName:'라벤더',trim:'#b86532',trimName:'번트 오렌지',material:'메리노 울',needle:4.5};
