document.addEventListener('change',async e=>{if(e.target.id!=='file-input')return;const files=[...e.target.files].slice(0,3);for(const f of files){if(f.size>1500000){toast('파일 하나당 1.5MB 이하로 첨부해 주세요.');continue;}if(f.type.startsWith('image/')){const data=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(f);});attachments.push({name:f.name,data});}else attachments.push({name:f.name});}if($('#attachment-tray'))$('#attachment-tray').innerHTML=attachments.map(a=>`${ico('attach')}${esc(a.name)}`).join(' · ');});
render();save();
const ctx=document.modelContext;if(ctx?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(ctx.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_knitting_project',description:'Read current design, gauge, compiled sleeve plan and knitting progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:project().name,design:project().design,gauge:project().gauge,profile:project().profile,calculated:calc(),compiled:compileDesign(project()),knitting:project().knitting||{},rowsDone:project().rowsDone})});register({name:'stage_sleeve_length_change',description:'Show an unapplied sleeve length proposal in the chat. The user applies it separately.',inputSchema:{type:'object',properties:{lengthCm:{type:'number',minimum:20,maximum:70}},required:['lengthCm'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.lengthCm!=='number'||!Number.isFinite(input.lengthCm)||input.lengthCm<20||input.lengthCm>70)throw new Error('lengthCm must be between 20 and 70');page='studio';stageChange('sleeve',input.lengthCm,'소매 길이 수정안');return{pending:project().pending};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function sleevePattern(p){return '<div class="knit-banner"><div><h3>오늘도, 멈춘 곳에서 한 단씩</h3><p>양쪽 소매의 진도와 다음 줄임 단을 따로 기억해요.</p></div><button class="button primary" data-action="knit-resume">소매 이어뜨기 →</button></div><section class="knit-pattern-section">'+designSummary(p)+designDetails(p)+'</section>';}
function printSleeve(p){const c=compileDesign(p),s=c.sleeve;if(!c.valid)return '<p>소매 조건을 다시 확인해 주세요.</p>';return '<h2>소매 · '+c.id+'</h2>'+(s.continuation?'<p>실측 '+s.continuation.measurement.rows+'단 / '+s.continuation.measurement.cm+'cm · 완료 '+s.continuation.lockedRows+'단 보존 · 이후 '+(s.rowsPerCm*10).toFixed(2)+'단/10cm 적용 ('+(s.continuation.measurement.state==='washed'?'세탁·건조 후':'세탁 전')+')</p>':'')+'<p>어깨 기준 요청 '+s.requestedCm+'cm → 계산 '+s.actualCm+'cm. 겨드랑이에서 '+s.startStitches+'코를 확보한 이후 '+s.underarmRows+'단. 요크 측 '+s.capRows+'단 상당의 고정 길이는 이 도안 밖의 구간입니다. 고무단은 적용한 소매 단 게이지로 환산하며 실제 게이지 확인이 필요합니다.</p><table style="width:100%;border-collapse:collapse;font-size:10px"><thead><tr><th>단</th><th>방법</th><th>완료 코 수</th></tr></thead><tbody>'+s.rounds.map(r=>'<tr><td>'+r.round+'</td><td>'+r.instruction+'</td><td>'+r.after+'</td></tr>').join('')+'</tbody></table><p>양쪽 소매 동일 적용. 마지막 단 이후 탄성 코막음은 별도로 진행합니다.</p>';}
function openKnitEditor(){const p=shownProject(),t={...TEMPLATE,...p.design.knit};modal('소매를 제작 조건으로 조정하기',`<p class="modal-description">길이와 둘레를 바꾸면 줄임 위치를 다시 계산해요.</p><form id="knit-editor-form" class="knit-editor-form"><div class="fields">${field('어깨부터 소맷단 길이 (cm)','knit-length',p.design.sleeve,20,70,.1)}${field('겨드랑이 소매 시작 둘레 (cm)','knit-upper',t.upperArmCm,24,60,.5)}${field('소맷단 둘레 (cm)','knit-cuff',t.cuffCm,12,36,.5)}${field('배색 고무단 길이 (cm)','knit-rib',t.cuffLengthCm,2,10,.5)}</div><p class="knit-editor-note">요크 측 소매 18cm는 고정하고 겨드랑이 아래를 계산합니다. 둘레는 4의 배수 코로, 고무단은 짝수 단으로 맞춰요. 줄임 사이에는 최소 2단을 확보합니다.</p><div id="knit-editor-status" class="knit-editor-status" aria-live="polite"></div><div class="modal-actions"><button class="button primary" type="submit">수정안 계산하기</button></div></form>`);}
function editorChanges(){return {sleeveRevision:null,sleeve:Number($('#knit-length').value),knit:{...project().design.knit,upperArmCm:Number($('#knit-upper').value),cuffCm:Number($('#knit-cuff').value),cuffLengthCm:Number($('#knit-rib').value)}};}
document.addEventListener('submit',e=>{if(e.target.id!=='knit-editor-form')return;e.preventDefault();const p=project(),changes=editorChanges(),candidate={...p,design:{...p.design,...changes}},c=compileDesign(candidate);if(!c.valid){$('#knit-editor-status').innerHTML='<div class="knit-error">'+c.errors.join('<br>')+'</div>';return;}const old=compileDesign(p),diff=compareDesign(old,c);p.pending={key:'knit',value:changes.knit,changes,title:'소매 구조 수정안',before:p.design.sleeve+'cm · '+old.sleeve.cuffStitches+'코',after:changes.sleeve+'cm · '+c.sleeve.cuffStitches+'코',impact:'총 '+c.sleeve.totalRows+'단 ('+(diff.rows>=0?'+':'')+diff.rows+'단). '+c.sleeve.startStitches+'코에서 '+c.sleeve.cuffStitches+'코까지 '+c.sleeve.decreaseCount+'회 줄임을 배치했어요. 양쪽 소매에 같은 규칙을 적용합니다.'};previewDraft=true;previewMode='3d';page='studio';save();closeModal();render();scrollChat();});
function handleKnitAction(action,value){if(handleMeasurement(action))return true;switch(action){case'knit-resume':modal('소매 이어뜨기',runnerMarkup(project(),knittingSide),act('close','닫기','','button'));return true;case'knit-side':knittingSide=value;handleKnitAction('knit-resume');return true;case'knit-step':updateProgress(project(),knittingSide,value);save();handleKnitAction('knit-resume');return true;case'knit-edit':openKnitEditor();return true;case'knit-details':modal('계산 근거 · 소매 단별 도안',designDetails(shownProject()),act('knit-json','설계 JSON 저장','','button')+act('close','확인','','button primary'),true);return true;case'knit-json':{const c=compileDesign(shownProject());download(new Blob([JSON.stringify(c,null,2)],{type:'application/json'}),c.id+'-design.json');return true;}case'structure-view':avatar?.setMode?.(value);document.querySelectorAll('[data-action="structure-view"]').forEach(b=>b.classList.toggle('active',b.dataset.value===value));return true;case'structure-angle':avatar?.angle?.(Number(value));document.querySelector('[data-action="structure-auto"]')?.setAttribute('aria-pressed','false');return true;case'structure-auto':{const on=avatar?.toggleAuto?.();document.querySelector('[data-action="structure-auto"]')?.setAttribute('aria-pressed',String(Boolean(on)));return true;}case'structure-export':{if(!avatar?.exportGuides){toast('360도 형태가 준비된 뒤 저장해 주세요.');return true;}const view=avatar,button=document.querySelector('[data-action="structure-export"]');button.disabled=true;button.textContent='8시점 가이드를 만드는 중…';view.exportGuides().then(blob=>{download(blob,view.plan.id+'-generation-guides.zip');toast('설계·단별 도안·8시점 가이드 32장을 저장했어요.');}).catch(e=>toast(e.message)).finally(()=>{if(button.isConnected){button.disabled=false;button.textContent='생성 가이드 8시점 저장 ↓';}});return true;}default:return false;}}

function measurementPending(r){return{key:'sleeve',value:r.changes.sleeve,changes:r.changes,title:'실측을 반영해 남은 소매 조정',before:r.before.sleeve.underarmRows+'단 · '+r.before.sleeve.requestedCm+'cm',after:r.after.sleeve.underarmRows+'단 · 목표 '+r.after.sleeve.requestedCm+'cm',impact:'완료 '+r.comparison.lockedRows+'단의 동작과 코 수를 보존합니다. '+(r.side==='left'?'왼쪽':'오른쪽')+' 소매는 '+(r.measurement.rows+1)+'단부터, 남은 '+r.comparison.remainingRows+'단을 이어 떠요. 고무단 '+r.after.sleeve.cuffRows+'단은 유지해요.',continuation:{sourcePlanId:r.before.id,sourceProgressFingerprint:r.sourceProgressFingerprint,progress:r.progress,measurement:r.measurement}};}
function handleMeasurement(action){
  if(action==='measurement-open'){
    if(project().pending){toast('작업실의 수정안을 먼저 적용하거나 취소해 주세요.');return true;}
    measurementDraft=null;modal('실측 입력 · 남은 도안 조정',measurementForm(project(),knittingSide));return true;
  }
  if(action==='measurement-back'){
    const input=measurementDraft?.input;modal('실측 입력 · 남은 도안 조정',measurementForm(project(),knittingSide));
    if(input)for(const [key,value]of Object.entries(input)){const field=$('#measurement-form [name="'+key+'"]');if(field)field.value=value;}
    return true;
  }
  if(action==='measurement-stage'){
    if(!measurementDraft)return true;const p=project(),q=measurementPending(measurementDraft.result);
    if(p.id!==measurementDraft.projectId||!continuationIsFresh(p,q)){toast('진도나 설계가 바뀌었어요. 다시 계산해 주세요.');return true;}
    p.pending=q;previewDraft=true;previewMode='3d';page='studio';save();closeModal();render();scrollChat();measurementDraft=null;return true;
  }
  return false;
}
document.addEventListener('submit',e=>{
  if(e.target.id!=='measurement-form')return;e.preventDefault();
  const input=Object.fromEntries(new FormData(e.target)),p=project(),result=prepareMeasurement(p,input);
  if(!result.valid){$('#measurement-errors').innerHTML='<div class="knit-error">'+result.errors.map(esc).join('<br>')+'</div>';return;}
  measurementDraft={projectId:p.id,input,result};modal('완료 구간을 지키는 수정안',measurementReview(result),act('measurement-back','입력 수정','','button')+act('measurement-stage','360°에서 수정안 확인','','button primary'),true);
});

function createDesignZoom(){
  const viewport=$('#design-image-viewport'),stage=viewport?.closest('.design-preview-stage'),image=viewport?.querySelector('.sweater-photo');
  if(!viewport||!stage||!image)return null;
  const level=stage.querySelector('.design-zoom-level'),expand=stage.querySelector('[data-action="design-expand"]'),zoomOut=stage.querySelector('[data-action="zoom-out"]'),zoomIn=stage.querySelector('[data-action="zoom"]');
  const pointers=new Map(),stops=[1,1.5,2,3,4],home=stage.parentNode,following=stage.nextSibling;
  let scale=1,offsetX=0,offsetY=0,expanded=false,observer;
  function clamp(){
    const width=viewport.clientWidth,height=viewport.clientHeight,sourceWidth=image.naturalWidth||1254,sourceHeight=image.naturalHeight||1254;
    if(!width||!height)return;
    const fit=Math.min(width/sourceWidth,height/sourceHeight);
    const maxX=Math.max(0,(sourceWidth*fit*scale-width)/2),maxY=Math.max(0,(sourceHeight*fit*scale-height)/2);
    offsetX=Math.max(-maxX,Math.min(maxX,offsetX));
    offsetY=Math.max(-maxY,Math.min(maxY,offsetY));
  }
  function draw(){
    clamp();
    image.style.transform='translate3d('+offsetX+'px,'+offsetY+'px,0) scale('+scale+')';
    level.textContent=Math.round(scale*100)+'%';
    viewport.classList.toggle('can-pan',scale>1.001);
    zoomOut.disabled=scale<=1.001;
    zoomIn.disabled=scale>=3.999;
  }
  function setZoom(next,clientX,clientY){
    next=Math.max(1,Math.min(4,next));
    if(Math.abs(next-scale)<.001){draw();return;}
    const rect=viewport.getBoundingClientRect(),px=Number.isFinite(clientX)?clientX-rect.left-rect.width/2:0,py=Number.isFinite(clientY)?clientY-rect.top-rect.height/2:0,ratio=next/scale;
    offsetX=ratio*offsetX+(1-ratio)*px;
    offsetY=ratio*offsetY+(1-ratio)*py;
    scale=next;
    draw();
  }
  function zoomBy(step){
    const next=step>0?(stops.find(value=>value>scale+.01)??4):([...stops].reverse().find(value=>value<scale-.01)??1);
    setZoom(next);
  }
  function reset(){scale=1;offsetX=0;offsetY=0;draw();}
  function toggleExpanded(force){
    expanded=typeof force==='boolean'?force:!expanded;
    if(expanded)document.body.append(stage);
    else if(stage.parentNode!==home)home.insertBefore(stage,following?.parentNode===home?following:null);
    stage.classList.toggle('is-expanded',expanded);
    document.body.classList.toggle('design-image-expanded',expanded);
    expand.setAttribute('aria-label',expanded?'큰 화면 닫기':'이미지 크게 보기');
    expand.setAttribute('aria-pressed',String(expanded));
    expand.title=expanded?'큰 화면 닫기':'이미지 크게 보기';
    draw();
  }
  function collapse(){if(expanded)toggleExpanded(false);}
  function onWheel(event){const next=scale*Math.exp(-event.deltaY*.0012);if((next<1&&scale<=1)||(next>4&&scale>=4))return;event.preventDefault();setZoom(next,event.clientX,event.clientY);}
  function onPointerDown(event){
    if(event.pointerType==='mouse'&&event.button!==0)return;
    viewport.setPointerCapture(event.pointerId);
    pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
    if(event.pointerType!=='touch'||scale>1||pointers.size>1)event.preventDefault();
  }
  function onPointerMove(event){
    if(!pointers.has(event.pointerId))return;
    const before=[...pointers.values()];
    pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
    const after=[...pointers.values()];
    let handled=false;
    if(after.length===1&&scale>1){
      handled=true;
      offsetX+=after[0].x-before[0].x;
      offsetY+=after[0].y-before[0].y;
      draw();
    }else if(after.length>=2){
      handled=true;
      const previousCenter={x:(before[0].x+before[1].x)/2,y:(before[0].y+before[1].y)/2};
      const currentCenter={x:(after[0].x+after[1].x)/2,y:(after[0].y+after[1].y)/2};
      offsetX+=currentCenter.x-previousCenter.x;
      offsetY+=currentCenter.y-previousCenter.y;
      const previousDistance=Math.hypot(before[0].x-before[1].x,before[0].y-before[1].y);
      const currentDistance=Math.hypot(after[0].x-after[1].x,after[0].y-after[1].y);
      if(previousDistance>0)setZoom(scale*currentDistance/previousDistance,currentCenter.x,currentCenter.y);
      else draw();
    }
    if(handled)event.preventDefault();
  }
  function onPointerUp(event){
    pointers.delete(event.pointerId);
    if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId);
  }
  function onDoubleClick(event){event.preventDefault();setZoom(scale>=3.999?1:Math.min(4,scale*2),event.clientX,event.clientY);}
  function onKeyDown(event){
    if(event.key==='+'||event.key==='='){zoomBy(1);event.preventDefault();}
    else if(event.key==='-'){zoomBy(-1);event.preventDefault();}
    else if(event.key==='0'){reset();event.preventDefault();}
    else if(event.key.startsWith('Arrow')&&scale>1){
      const step=48;
      if(event.key==='ArrowLeft')offsetX-=step;
      if(event.key==='ArrowRight')offsetX+=step;
      if(event.key==='ArrowUp')offsetY-=step;
      if(event.key==='ArrowDown')offsetY+=step;
      draw();
      event.preventDefault();
    }
  }
  viewport.addEventListener('wheel',onWheel,{passive:false});
  viewport.addEventListener('pointerdown',onPointerDown);
  viewport.addEventListener('pointermove',onPointerMove);
  viewport.addEventListener('pointerup',onPointerUp);
  viewport.addEventListener('pointercancel',onPointerUp);
  viewport.addEventListener('dblclick',onDoubleClick);
  viewport.addEventListener('keydown',onKeyDown);
  image.addEventListener('load',draw);
  if('ResizeObserver'in window){observer=new ResizeObserver(draw);observer.observe(viewport);}
  else window.addEventListener('resize',draw);
  draw();
  return{zoomBy,reset,toggleExpanded,collapse,dispose(){
    viewport.removeEventListener('wheel',onWheel);
    viewport.removeEventListener('pointerdown',onPointerDown);
    viewport.removeEventListener('pointermove',onPointerMove);
    viewport.removeEventListener('pointerup',onPointerUp);
    viewport.removeEventListener('pointercancel',onPointerUp);
    viewport.removeEventListener('dblclick',onDoubleClick);
    viewport.removeEventListener('keydown',onKeyDown);
    image.removeEventListener('load',draw);
    observer?.disconnect();
    window.removeEventListener('resize',draw);
    if(stage.parentNode===document.body){
      if(home.isConnected)home.insertBefore(stage,following?.parentNode===home?following:null);
      else stage.remove();
    }
    document.body.classList.remove('design-image-expanded');
  }};
}
